"""Finite compile diagnostics only; importing this module performs no I/O."""
from pathlib import Path
import os
import re
import stat

LIMIT = 65536
CODES = frozenset({
    'C1001', 'C1083', 'C1900', 'C2011', 'C2027', 'C2039', 'C2059', 'C2061',
    'C2065', 'C2079', 'C2143', 'C2146', 'C2371', 'C2440', 'C2512', 'C2660',
    'C2664', 'C2672', 'C3646', 'C3861', 'C4430', 'LNK1104', 'LNK1120', 'LNK2001', 'LNK2019',
})
STAGES = frozenset({'preparation', 'tools-record', 'command-write', 'build-command',
                    'devcmd', 'tool-versions', 'compile-link', 'tool-metadata'})
READ_STATES = frozenset({'missing', 'truncated', 'read-failed', 'changed', 'not-regular'})


def classify_compile_log(data, source_lines, phase, read_state='complete'):
    """Classify authored or bounded bytes. Never return diagnostic text or a path."""
    result = {'phase': phase if type(phase) is str and phase in STAGES else 'unclassified',
              'status': 'unknown', 'code': 'unknown', 'line': 'unknown'}
    if read_state != 'complete':
        result['status'] = read_state if type(read_state) is str and read_state in READ_STATES else 'unknown'
        return result
    if type(data) is not bytes or len(data) > LIMIT:
        result['status'] = 'truncated' if type(data) is bytes else 'unknown'
        return result
    if type(source_lines) is not int or not 1 <= source_lines <= 100000:
        result['status'] = 'source-unknown'
        return result
    if result['phase'] != 'compile-link':
        result['status'] = 'stage-only'
        return result
    try:
        text = data.decode('utf-16') if data.startswith((b'\xff\xfe', b'\xfe\xff')) else data.decode('utf-8-sig')
        if '\x00' in text:
            raise UnicodeError()
    except UnicodeError:
        result['status'] = 'unsupported-encoding'
        return result
    match = re.search(r'(?m)^[^\r\n]*?\b(?:fatal[ \t]+)?error[ \t]+(C[0-9]{4}|LNK[0-9]{4})[ \t]*:', text)
    if not match:
        result['status'] = 'no-code'
        return result
    code = match.group(1)
    if code not in CODES:
        result['status'] = 'unlisted-code'
        return result
    result.update(status='observed-code', code=code)
    # Only the fixed translation-unit basename and a positive, bounded line.
    prefix = match.group(0)
    line = re.search(r'(?:^|[/\\])authority\.cc\(([1-9][0-9]{0,5})(?:,[1-9][0-9]{0,5})?\)[ \t]*:[ \t]*(?:fatal[ \t]+)?error[ \t]+' + code + r'[ \t]*:$', prefix)
    if line and int(line.group(1)) <= source_lines:
        result['line'] = str(int(line.group(1)))
    return result


def read_bounded(file, maximum):
    """One read, never maximum+1; unstable or failed reads remain unknown."""
    try:
        before = file.lstat()
        if not stat.S_ISREG(before.st_mode):
            return 'not-regular', None
        if before.st_size > maximum:
            return 'truncated', None
        with file.open('rb') as stream:
            data = stream.read(maximum)
        after = file.stat()
        if len(data) != before.st_size or any(getattr(before, key) != getattr(after, key)
                for key in ('st_dev', 'st_ino', 'st_size', 'st_mtime_ns')):
            return 'changed', None
        return 'complete', data
    except FileNotFoundError:
        return 'missing', None
    except OSError:
        return 'read-failed', None


def main():
    root = Path(os.environ['HUB_COMPILE_ROOT'])
    phase = os.environ.get('HUB_COMPILE_DIAGNOSTIC_STAGE', '')
    if phase == 'build-command':
        state, raw = read_bounded(root / 'build-stage.txt', 64)
        phase = raw.decode('ascii').strip() if state == 'complete' and raw is not None else ''
        if phase not in {'devcmd', 'tool-versions', 'compile-link'}:
            phase = ''
    source_state, source = read_bounded(root / 'source/tests/native/windows-installer-authority/authority.cc', 1048576)
    source_lines = len(source.splitlines()) if source_state == 'complete' and source is not None else None
    state, raw = read_bounded(root / 'logs/compile.log', LIMIT)
    result = classify_compile_log(raw, source_lines, phase, state)
    # Every value is generated by the closed classifier; no raw log/env data.
    output = ''.join('diag_' + key + '=' + result[key] + '\n' for key in ('phase', 'status', 'code', 'line'))
    with Path(os.environ['GITHUB_OUTPUT']).open('a', encoding='ascii', newline='\n') as stream:
        stream.write(output)


if __name__ == '__main__':
    main()
